applicable_items.value:
let n1 = {{.Initial_Applicable_Items_Rule.output[0]}}
let n2 = {{.Conditional_Applicable_Items_Resolution_Rule.output}}

let cond = {}
n2.forEach(r => {
  let row = r.output[0]
  let v = String(row.requirement).toLowerCase()
  cond[row.item] = v.indexOf("required") === 0 ? "required" : v
})

let MAP = {
  "Loan_posting_credit_entry_to_the_loan": null,
  "Bill_payment_notice": "bill_notice",
  "Interest_calculation_worksheet": null,
  "Deposit_credit_wire_clearing_entry": null,
  "Fee_posting": "fee_posting",
  "Loan_history_posting_confirmation": "loan_history",
  "Rate_adjustment_evidence": "rate_adjustment",
  "GL_journal_cross_application_movement": null,
  "Suspense_posting_evidence": "suspense_evidence"
}

let applicable = []
Object.keys(MAP).forEach(k => {
  let base = String(n1[k]).toLowerCase()
  let status = base === "conditional" && cond[MAP[k]] != null ? cond[MAP[k]] : base
  if (status === "required") { applicable.push(k) }
})

applicable

